160	  const handleTopTabClick = (tabName: 'box' | 'settings' | 'developer' | 'params') => {
161	    if (tabName === 'settings' && !isModeling) {
162	      // Signale DÈS LE CLIC — avant même que le rideau plein écran ne commence à monter, pas
163	      // seulement une fois l'écran couvert (`onCovered`, ~900ms plus tard) — que les éléments sans
164	      // place dans l'espace Modélisation (ModelStatusBox, panneau du bas de Prévisualisation)
165	      // doivent commencer à disparaître : ce fondu-glissement doit être visible EN TRANSPARENCE À
166	      // TRAVERS le rideau (z-index 1000+ pour ces éléments, contre 30 pour le rideau), jamais
167	      // caché derrière lui comme le vrai changement d'onglet (`onTabChange`, lui, reste dans
168	      // `onCovered` ci-dessous : le panneau Modélisation ne doit apparaître qu'une fois l'écran
169	      // couvert).
170	      window.dispatchEvent(new CustomEvent('apex-entering-modeling'));
171	    } else if (tabName !== 'settings' && isModeling) {
172	      // Symétrique : le contenu du panneau Modélisation disparaît en cascade dès le clic, avant
173	      // que sa forme ne commence à se déformer (à `onCovered`, cf. ModelingSidebar).
174	      window.dispatchEvent(new CustomEvent('apex-leaving-modeling'));
175	    }
176	    playSpaceTransition(tabName, () => {
177	      setActiveTool('select');
178	      onTabChange(tabName);
179	      setIsPreviewActive(false);
180	      window.dispatchEvent(new CustomEvent('apex-preview-toggled', { detail: { active: false } }));
181	    });
182	  };
183	
184	  const handleToolClick = (tool: 'select' | 'move' | 'rotate' | 'scale' | 'texture') => {
185	    const newTool = activeTool === tool ? 'select' : tool;
186	    setActiveTool(newTool);
187	    window.dispatchEvent(new CustomEvent('apex-tool-changed', { detail: { tool: newTool } }));
188	  };
189	
190	  /**
191	   * Bascule animée vers l'espace Prévisualisation (rideau + déformation de la pilule), factorisée
192	   * hors de `handleLayerClick` pour être aussi déclenchée par le dépôt d'un fichier G-code en
193	   * Préparation (cf. l'écouteur `drop` plus bas) — même geste que le clic sur l'icône Prévisualisation,
194	   * simplement déclenché autrement. `pendingFile`, s'il est fourni, est réémis (`apex-gcode-loaded`
195	   * en pointillé via `apex-entering-preview-with-file`) une fois l'écran couvert, PAS avant : au
196	   * moment du dépôt, l'espace Prévisualisation n'a pas encore son hook de lecture actif
197	   * (`useGCodePreview(isPreviewActive)` dans Index.tsx), lequel n'écoute le dépôt/chargement que
198	   * lorsque `active` — le charger avant ce basculement n'aurait donc aucun effet.
199	   */
200	  const enterPreview = (pendingFile?: File) => {
201	    // Depuis Modélisation : même signal au clic que handleTopTabClick (cf. apex-leaving-modeling).
202	    if (isModeling) window.dispatchEvent(new CustomEvent('apex-leaving-modeling'));
203	    // L'ancien fondu séquencé des panneaux (avant le rideau plein écran) n'a plus de raison
204	    // d'être : le rideau masque déjà tout pendant que ce switch se produit, donc tout bascule
205	    // d'un coup sous le voile plutôt qu'en deux temps visibles.
206	    playSpaceTransition('layers', () => {
207	      setActiveTool('layers');
208	      // Prévisualisation est un sous-mode du slicer (Préparation), jamais de la
209	      // Modélisation : sans ce `onTabChange`, entrer en Prévisualisation depuis
210	      // Modélisation laissait `activeTab` sur 'settings', et donc le bouton
211	      // "Modélisation" restait actif (cyan) par-dessus "Prévisualisation". Le second argument
212	      // signale spécifiquement ce cas-là à Index.tsx (venant de Modélisation, vers
213	      // Prévisualisation et non vers Préparation), pour qu'il joue le bon morph de sortie.
214	      onTabChange('box', true);
215	      setIsPreviewActive(true);
216	      window.dispatchEvent(new CustomEvent('apex-tool-changed', { detail: { tool: 'layers' } }));
217	      window.dispatchEvent(new CustomEvent('apex-preview-toggled', { detail: { active: true } }));
218	      // Dispatché en DERNIER, une fois `apex-preview-toggled` déjà parti : useGCodePreview
219	      // (Index.tsx) doit être passé à `active` avant de recevoir le fichier, sans quoi son
220	      // écouteur de dépôt (qui double aussi comme point d'entrée de chargement, cf.
221	      // use-gcode-preview.ts) ignorerait l'événement.
222	      if (pendingFile) {
223	        window.dispatchEvent(new CustomEvent('apex-entering-preview-with-file', { detail: { file: pendingFile } }));
224	      }
225	    });
226	  };
227	
228	  const handleLayerClick = () => {
229	    const entering = activeTool !== 'layers';
230	
231	    if (entering) {
232	      enterPreview();
233	    } else {
234	      playSpaceTransition('box', () => {
235	        setActiveTool('select');
236	        setIsPreviewActive(false);
237	        window.dispatchEvent(new CustomEvent('apex-tool-changed', { detail: { tool: 'select' } }));
238	        window.dispatchEvent(new CustomEvent('apex-preview-toggled', { detail: { active: false } }));
239	      });
240	    }
241	  };
242	
243	  // Dépôt d'un fichier G-code n'importe où dans la fenêtre pendant qu'on est en Préparation (hors
244	  // Prévisualisation, hors Modélisation) : bascule automatiquement vers l'espace Prévisualisation,
245	  // avec la même animation que le clic sur son icône, puis charge le fichier une fois l'écran
246	  // découvert (cf. `enterPreview`). Un simple survol (dragenter/dragover) sans dépôt ne déclenche
247	  // rien — jamais de bascule sur un simple passage de fichier au-dessus de la fenêtre.
248	  useEffect(() => {
249	    if (isPreviewActive || isModeling) return;
250	    const hasFiles = (e: DragEvent) => !!e.dataTransfer?.types.includes('Files');
251	    const onDragOver = (e: DragEvent) => {
252	      if (!hasFiles(e)) return;
253	      e.preventDefault();
254	      if (e.dataTransfer) e.dataTransfer.dropEffect = 'copy';
255	    };
256	    const onDrop = (e: DragEvent) => {
257	      if (!hasFiles(e)) return;
258	      const file = e.dataTransfer?.files?.[0];
259	      if (!file || !GCODE_FILE_EXT.test(file.name)) return;
260	      e.preventDefault();
261	      enterPreview(file);
262	    };
263	    window.addEventListener('dragover', onDragOver);
264	    window.addEventListener('drop', onDrop);
265	    return () => {
266	      window.removeEventListener('dragover', onDragOver);
267	      window.removeEventListener('drop', onDrop);
268	    };
269	    // eslint-disable-next-line react-hooks/exhaustive-deps
270	  }, [isPreviewActive, isModeling]);
271	
272	  useEffect(() => {
273	    const handleKeyDown = (e: KeyboardEvent) => {
274	      const target = e.target as HTMLElement | null;
275	      if (target && (['INPUT', 'TEXTAREA'].includes(target.tagName) || target.isContentEditable)) {
276	        return;
277	      }
278	
279	      const key = e.key.toLowerCase();
280	      if (key === 'm') {
281	        const newTool = activeTool === 'move' ? 'select' : 'move';
282	        setActiveTool(newTool);
283	        window.dispatchEvent(new CustomEvent('apex-tool-changed', { detail: { tool: newTool } }));
284	      } else if (key === 'r') {
285	        const newTool = activeTool === 'rotate' ? 'select' : 'rotate';
286	        setActiveTool(newTool);
287	        window.dispatchEvent(new CustomEvent('apex-tool-changed', { detail: { tool: newTool } }));
288	      } else if (key === 's') {
289	        const newTool = activeTool === 'scale' ? 'select' : 'scale';
290	        setActiveTool(newTool);
291	        window.dispatchEvent(new CustomEvent('apex-tool-changed', { detail: { tool: newTool } }));
292	      } else if (key === 't') {
293	        const newTool = activeTool === 'texture' ? 'select' : 'texture';
294	        setActiveTool(newTool);
295	        window.dispatchEvent(new CustomEvent('apex-tool-changed', { detail: { tool: newTool } }));
296	      } else if (key === 'escape') {
297	        setActiveTool('select');
298	        window.dispatchEvent(new CustomEvent('apex-tool-changed', { detail: { tool: 'select' } }));
