 37	const Index = () => {
 38	  const [activeTab, setActiveTab] = useState<'3d-view' | 'settings' | 'developer' | 'params'>('3d-view');
 39	  const [activeCategory, setActiveCategory] = useState<string | null>(null);
 40	  const [isPrinterConfigOpen, setIsPrinterConfigOpen] = useState(false);
 41	  const [selectedPrinter, setSelectedPrinter] = useState('Prusa MK4');
 42	  const [selectedFilament, setSelectedFilament] = useState('PLA Premium (eSUN / Prusament)');
