 44	  const [isSlicingProgressOpen, setIsSlicingProgressOpen] = useState(false);
 45	  const [modelStatus, setModelStatus] = useState<ModelStatus | null>(null);
 46	  const [isPreviewActive, setIsPreviewActive] = useState(false);
 47	  const isPreviewActiveRef = useRef(isPreviewActive);
 48	  isPreviewActiveRef.current = isPreviewActive;
 49	  // Logique de l'espace Prévisualisation (chargement/lecture G-code) : appelée ici (et non dans
 50	  // GCodePreview) car sa barre de lecture (GCodePreviewBar) partage la rangée du bas avec la
 51	  // pastille de statut du plateau, ce qui demande que les deux soient des enfants directs du même
 52	  // conteneur flex plutôt que des composants positionnés indépendamment.
 53	  const gcodePreview = useGCodePreview(isPreviewActive);
 54	  // Le temps que ModelingSidebar déforme sa propre silhouette entre la forme de la pilule/des deux
 55	  // panneaux de Prévisualisation et sa forme normale — cf. le commentaire sur `onTabChange` plus
 56	  // bas et le prop `morph` de ModelingSidebar. `null` = pas de morph en cours ; sinon, `direction`
 57	  // indique le sens ('enter' : la pilule/Prévisualisation devient le panneau Modélisation, 'exit' :
 58	  // l'inverse) et `fromPreview` l'état de Prévisualisation à l'autre bout du morph (pilule ou
 59	  // panneaux Preview) — figé à l'instant du clic, lu depuis isPreviewActiveRef, PAS depuis
 60	  // isPreviewActive : Sidebar mute ce dernier dans le même geste, avant qu'on ait la chance de lire
 61	  // sa valeur de départ. Contrairement à l'ancienne approche (deux calques à synchroniser — un
 62	  // verre animé séparé, puis le vrai panneau), c'est ICI le même élément, déjà affiché avec son
 63	  // contenu réel, qui change de forme : plus de raccord entre deux éléments distincts, donc plus
 64	  // de risque de clignotement à la jonction.
 65	  const [modelingMorph, setModelingMorph] = useState<{ direction: 'enter' | 'exit'; fromPreview: boolean } | null>(null);
