 70	  // lui reste cadencé par `onCovered`. Redevient faux une fois le morph 'enter' effectivement lancé
 71	  // (le panneau du bas a alors largement eu le temps de finir sa disparition, 260ms contre les
 72	  // ~900ms d'attente du rideau).
 73	  const [leavingToModeling, setLeavingToModeling] = useState(false);
 74	  const [statusBarRef, animateStatusBar] = useAnimate<HTMLDivElement>();
 75	  const prevPreviewActiveRef = useRef(isPreviewActive);
 76	
